/**
 * @file        contains the implementation of two Event Bus' channel types:
 *
 *              PrivateChannel - channel used to 1v1 communication between for example canvas and widget instance.
 *
 *              GlobalChannel - channel used to broadcast the information about creating and closing new PrivateChannel.
 *
 * @author      Michał Włodarczyk <m.wlodarczy3@samsung.com>
 * @copyright   Copyright (c) 2023 Samsung Electronics, B2B & Cloud Division. All Rights Reserved.
 */

import { chooseMethod } from './chooseMethod';
import { deleteLocalStorage } from './localstorage';
import {
    PrivateEventBusChannel,
    SubscribedEventTypes,
    EventType,
    SubscribeCallback,
    EventBusChannelMessage,
    GlobalEventBusChannel,
    GlobalChannelPublishPayload,
    GlobalChannelSubscribeCallback,
    PendingPromises
} from './types';
import { BroadcastChannel, MethodType } from 'broadcast-channel';

const pendingPromises = ((): PendingPromises => {
    const promises: Map<string, { resolve: Function; reject: Function }> =
        new Map();

    const incrementId: () => string = (() => {
        let increment = 0;
        return () => {
            increment += 1;
            return String(Date.now() + increment);
        };
    })();

    return {
        add(resolve: Function, reject: Function) {
            const key = incrementId();
            promises.set(key, { resolve, reject });
            return key;
        },
        resolve(key: string, data: any) {
            promises.get(key)?.resolve(data);
            promises.delete(key);
        },
        reject(key: string, data: any) {
            promises.get(key)?.reject(data);
            promises.delete(key);
        }
    };
})();

export class PrivateChannel implements PrivateEventBusChannel {
    public id: string;

    private subscribedEventTypes: SubscribedEventTypes;
    private broadcastChannel: BroadcastChannel;

    private globalCloseChannelId: string = 'close-channel-broadcaster';
    private globalCloseChannel: GlobalEventBusChannel;
    private broadcastChannelType: MethodType;

    constructor(channelId: string) {
        this.id = channelId;
        this.subscribedEventTypes = {};

        this.broadcastChannelType = chooseMethod();

        this.broadcastChannel = new BroadcastChannel(this.id, {
            type: this.broadcastChannelType
        });
        this.channelMessageHandler();

        this.globalCloseChannel = new GlobalChannel(this.globalCloseChannelId);

        this.initializeGlobalCloseChannel();
    }

    public publishAsync<T>(type: EventType, payload: T): Promise<any> {
        return new Promise((resolve, reject) => {
            const publishId = pendingPromises.add(resolve, reject);
            this.publishMessage<T>(type, payload, publishId);
        });
    }

    public publish<T>(type: EventType, payload: T): void {
        this.publishMessage<T>(type, payload);
    }

    public subscribe(type: EventType, callback: SubscribeCallback): void {
        this.subscribedEventTypes[type] = callback;
    }

    public unsubscribe(type: EventType): void {
        this.subscribedEventTypes[type] = undefined;
    }

    public close(): void {
        this.closeBroadcastChannel();
        this.broadcastChannelClosing();
    }

    public isClosed(): boolean {
        return (
            this.broadcastChannel.isClosed && this.globalCloseChannel.isClosed()
        );
    }

    private publishMessage<T>(
        type: EventType,
        payload: T,
        publishId?: string
    ): void {
        const eventMessage: EventBusChannelMessage<T> = {
            type: type,
            payload: payload
        };
        if (publishId) {
            eventMessage['publishId'] = publishId;
        }

        this.broadcastChannel.postMessage(eventMessage).catch(() => {
            throw new Error(`<event-bus> ${this.id} channel has been closed`);
        });
    }

    private initializeGlobalCloseChannel(): void {
        this.globalCloseChannel.subscribe(
            ({
                channelName,
                killAll
            }: {
                channelName: string;
                killAll?: boolean;
            }) => {
                if (
                    killAll &&
                    channelName &&
                    channelName === this.id &&
                    this.broadcastChannel
                ) {
                    this.closeBroadcastChannel();
                    if (!this.globalCloseChannel.isClosed()) {
                        this.globalCloseChannel.close();
                    }
                }
            }
        );
    }

    private closeBroadcastChannel(): void {
        // Closes the private broadcastChannel used in 1 to 1 communication.
        if (!this.broadcastChannel.isClosed) {
            this.broadcastChannel.close();
        }

        // localStorage must be cleared so that it does not overflow its capacity (the capacity of localStorage is 10Mb)
        if (this.broadcastChannelType === 'localstorage') {
            deleteLocalStorage(this.id);
        }
    }

    private broadcastChannelClosing(): void {
        // Closing the globalCloseChannel if it wasn't closed from onmessage.
        if (!this.globalCloseChannel.isClosed()) {
            // The postMessage is being fired on the globalCloseChannel to inform about closing of this channel.
            this.globalCloseChannel.publish({
                channelName: this.id,
                killAll: false
            });
            // Closing the globalCloseChannel.
            this.globalCloseChannel.close();
        }
    }

    private channelMessageHandler(): void {
        if (this.broadcastChannel) {
            this.broadcastChannel.onmessage = (
                messagePayload: EventBusChannelMessage<any>
            ) => {
                if (messagePayload) {
                    const { type, payload, publishId } = messagePayload;
                    this.eventTypesCallbackHandler(type, payload, publishId);
                }
            };
        }
    }

    private eventTypesCallbackHandler(
        type: EventType,
        payload: any,
        publishId?: string
    ): void {
        const mappedEvent = this.subscribedEventTypes[type];
        if (mappedEvent) {
            const mappedEventRes = mappedEvent(payload);
            if (publishId) {
                if (mappedEventRes instanceof Promise) {
                    mappedEventRes
                        .then((res) => pendingPromises.resolve(publishId, res))
                        .catch((error) =>
                            pendingPromises.reject(publishId, error)
                        );
                } else {
                    pendingPromises.resolve(publishId, mappedEventRes);
                }
            }
        }
    }
}

export class GlobalChannel implements GlobalEventBusChannel {
    public id: string;
    private broadcastChannel: BroadcastChannel;
    private broadcastChannelType: MethodType;

    constructor(channelId: string) {
        this.id = channelId;
        this.broadcastChannelType = chooseMethod();
        this.broadcastChannel = new BroadcastChannel(this.id, {
            type: this.broadcastChannelType
        });
    }

    public publish(payload: GlobalChannelPublishPayload): void {
        if (!this.isClosed()) {
            this.broadcastChannel.postMessage(payload);
        }
    }

    public subscribe(callback: GlobalChannelSubscribeCallback): void {
        this.broadcastChannel.onmessage = ({
            channelName,
            killAll
        }: GlobalChannelPublishPayload) => {
            callback({ channelName, killAll });
        };
    }

    public close() {
        this.broadcastChannel.close();
    }

    public isClosed() {
        return this.broadcastChannel.isClosed;
    }
}
