/**
 * @file        contains an implementation of the Event Bus object which organizes the WiNE API communication channels.
 *              Exposes 3 different methods:
 *
 *              @param privateChannelId - id for the new channel, used to differentiate it between other private
 *              channels.
 *              @return new PrivateChannel object with the provided id.
 *              createChannel(privateChannelId)
 *
 *              @param channelId - id of the channel to be closed
 *              closeChannel(channelId)
 *
 *              @param callback - callback function which is going to be exectued when a new channel is being created
 *              @returns new GlobalChannel object subscribed to the ChannelOpened event (used to broadcast the
 *              information about newly created channels) with the provided callback function.
 *              onChannelOpen(callback)
 *
 * @author      Michał Włodarczyk <m.wlodarczy3@samsung.com>
 * @copyright   Copyright (c) 2023 Samsung Electronics, B2B & Cloud Division. All Rights Reserved.
 */

import { PrivateChannel, GlobalChannel } from './channels';
import {
    EventBusInterface,
    GlobalEventBusChannel,
    OnChannelCloseCallback,
    OnChannelOpenCallback,
    PrivateEventBusChannel
} from './types';

declare const window: Window &
    typeof globalThis & {
        $vxtSubChannelId: string;
    };

export class EventBus implements EventBusInterface {
    private globalOpenChannelId: string;
    private globalOpenChannel: GlobalChannel;

    private globalCloseChannelId: string = 'close-channel-broadcaster';
    private globalCloseChannel: GlobalChannel;

    constructor(globalChannelId: string = 'ChannelOpened') {
        this.globalOpenChannelId = globalChannelId;
        this.globalOpenChannel = new GlobalChannel(this.globalOpenChannelId);
        this.globalCloseChannel = new GlobalChannel(this.globalCloseChannelId);
    }

    public createChannel(privateChannelId: string): PrivateChannel {
        const createdChannel = new PrivateChannel(privateChannelId);
        this.globalOpenChannel.publish({ channelName: createdChannel.id });

        return createdChannel;
    }

    public closeChannel(channelName: string): void {
        this.globalCloseChannel.publish({ channelName, killAll: true });
    }

    public onChannelOpen(callback: OnChannelOpenCallback): GlobalChannel {
        const openChannelBroadcastChannel = new GlobalChannel(
            this.globalOpenChannelId
        );
        const createNewChannelCallback = ({
            channelName
        }: {
            channelName: string;
        }) => {
            return callback({ id: channelName });
        };
        openChannelBroadcastChannel.subscribe(createNewChannelCallback);
        return openChannelBroadcastChannel;
    }

    public onChannelClose(callback: OnChannelCloseCallback): GlobalChannel {
        const closeChannelBroadcastChannel = new GlobalChannel(
            this.globalCloseChannelId
        );
        const internalCallback = ({
            channelName,
            killAll
        }: {
            channelName: string;
            killAll?: boolean;
        }) => {
            if (!killAll) {
                callback(channelName);
            }
        };
        closeChannelBroadcastChannel.subscribe(internalCallback);
        return closeChannelBroadcastChannel;
    }
}

export { GlobalEventBusChannel, PrivateEventBusChannel };
